#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT  ?x
WHERE {
  ns:m.0fjp3 ns:sports.sports_championship.events ?x . # World Series
  {
    { ?x ns:sports.sports_championship_event.runner_up ns:m.01yhm . } # Cleveland Indians
    UNION
    { ?x ns:sports.sports_championship_event.champion ns:m.01yhm . } # Cleveland Indians
  }
  ?x ns:time.event.start_date ?d .
}

#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
ns:m.0cb3n ns:fictional_universe.fictional_organization.sub_organization_in_fiction ?x .
}

#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT  ?x
WHERE {
  ns:m.03cv24 ns:organization.organization.date_founded	?d . # United States Department of the Navy
  ns:m.060d2 ns:government.government_office_or_title.office_holders ?y . # President of the United States
  ?y ns:government.government_position_held.from ?from ;
     ns:government.government_position_held.to ?to ;
     ns:government.government_position_held.office_holder ?x .
  FILTER(xsd:dateTime(?from) - xsd:dateTime(?d) <= 0)
  FILTER(xsd:dateTime(?to) - xsd:dateTime(?d) >= 0)
}

#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
  ns:m.06x5s ns:time.recurring_event.instances ?x . # Super Bowl instances

  {
    ?x ns:sports.sports_championship_event.champion ns:m.05gg4 . # giants
  }
  UNION
  {
    ?x ns:sports.sports_championship_event.runner_up ns:m.05gg4 . # giants
  }
  ?x ns:time.event.start_date ?st .
}
ORDER BY DESC(xsd:datetime(?st))
LIMIT 1

#MANUAL SPARQL
